// import the functions from irissdk
const { irissdk } = require('./import_irissdk.js')
const os = require('node:os')

// wrap irissdk functions for easier parameter passing
function __mandatory (parname) {
  throw new Error('ValueError: ' + parname + ' is required')
}


function createConnection ({
  host = '',
  port = undefined,
  ns = '',
  user = '',
  pwd = '',
  timeout = 10, // seconds
  sharedmemory = true,
  logfile = '',
  sslconfig = false
} = {}, callback = undefined) {

  let error = undefined

  // >>> Validate connection parameters 

  try {
    
    // mandatory args check
    if (ns.length == 0) __mandatory('ns')
    if (host.length == 0) __mandatory('host')
    if (port === undefined) __mandatory('port')
    

    // out of limits check
    if (host.length > 255) throw Error('ValueError: invalid host')
    // if (port < 0 || port > 65536) throw Error(`ValueError: invalid port: ${port}`) // --> moved in the core
    if (ns.length > 255) throw Error(`ValueError: invalid ns: ${ns}`)
    if (timeout < 0) throw Error(`ValueError: invalid timeout: ${timeout}`)
    if (logfile.length > 255) throw Error(`ValueError: invalid logfile: ${logfile}`)
    if (sslconfig.length > 255) throw Error(`ValueError: invalid sslcontext file: ${logfile}`)
   
    // Do not allow "true" value in Unix
    if (os.platform() !== 'win32' && sslconfig === true) {
      throw Error('ValueError: This value (true) is not allowed on Unix machines.')
    }      
  
  } catch (err) {
    error = err // save to properly throw in case callback is provided
  }

  // >>> Update parameters
  
  if (logfile == '') {
    // check for IRISNATIVELOG
    logfile = process.env.IRISNATIVELOG || '-'
  }

  // '-' is a value (and any string value) that will trigger a Registry search first and an SSLDefs.ini search after that.
  // It is unlikely for an ssl configuration to be defined as '-' in the registry, this is why this value is used.
  // Consider changing this value in the future

  sslconfig = (sslconfig === false) || (sslconfig === null)   ?
              undefined                                       :
              sslconfig === true ? '-' : sslconfig      


  // >>> Define connection action
  
  
  let doConnect = () => {
    
    // if error above, rethrow
    if (error) throw error
    
    const connection = new irissdk.Connection()
    
    try {
      connection.connect(host, port, ns, user, pwd, timeout, sharedmemory, logfile, sslconfig)
      return connection
    } catch (err) {

      if (err.message) {
        if (err.message.includes('<SSL Error>')) {
          err.message = err.message.replace('<SSL Error>', '<SSL Error> Please validate your server/client TLS configuration and try again. \nMore info: ')
          err.message = err.message.replace('unknown ca', 'unknown ca. certificate verify failed ')
        }
      }

      connection.close()

      throw err
    }

  }


  // >>> Perform connection sync or async depending on callback argument present 
  
  // Backward compatible implementation

  if (callback) {
    setTimeout(() => {
      try {
        const connection = doConnect()
        callback(undefined, connection)
      } catch (err) {
        callback(err)
      }
    }, 0)
  } else {
    const connection = doConnect()
    return connection
  }

  
}
 
module.exports.createConnection = createConnection
